<?php $pageTitle='My Attendance'; require_once __DIR__.'/../includes/header.php';$st=$pdo->prepare("SELECT a.* FROM attendance a JOIN students s ON s.id=a.student_id WHERE s.user_id=? ORDER BY a.attendance_date DESC");$st->execute([user()['id']]);$rows=$st->fetchAll();?><h2>My Attendance</h2><div class="card p-3"><table class="table"><thead><tr><th>Date</th><th>Status</th><th>Note</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['attendance_date'])?></td><td><?=e($r['status'])?></td><td><?=e($r['note'])?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/footer.php';